if __name__ == "__main__":
    find_module_path("bls")
    find_module_path("bplib")

    # Try to find submodules
    try:
        find_module_path("bls.scheme")
    except:
        print("Error finding bls.scheme")

    try:
        find_module_path("bplib.bp")
    except:
        print("Error finding bplib.bp")

