        if os.path.exists(path):
            for root, dirs, files in os.walk(path):
                for dir in dirs:
                    if dir in ["bls", "bplib"]:
                        mod_path = os.path.join(root, dir)
                        print(f"Found {dir} directory: {mod_path}")
                        # List files in the directory
                        print(f"Files in {dir}:")
                        for mod_file in os.listdir(mod_path):
